import { createRouter } from '@tanstack/react-router'
import { RouteErrorPage } from '~/components/ErrorPage'
// Generated by the TanStack Start plugin from the files in src/routes/. Never edit it by hand.
import { routeTree } from './routeTree.gen'

// Start calls this once per request on the server, and once in the browser.
// A function (not one shared router) so that two users' requests never share state.
export function getRouter() {
  return createRouter({
    routeTree,
    // When going back to a page, scroll to where you were on it.
    scrollRestoration: true,
    // When the pointer rests on a <Link> (or a link gets keyboard focus), start loading that
    // page's code and run its loader. By the click, it's often ready. The router keeps that
    // data for 30 seconds (`defaultPreloadStaleTime`), so the click doesn't load it again.
    defaultPreload: 'intent',
    // Every route without its own `errorComponent` shows this when its loader or component
    // throws. It renders in the parent's <Outlet />, so for a page that's inside the layout.
    defaultErrorComponent: RouteErrorPage,
  })
}
